<script setup>
import { computed, ref, useId } from 'vue'
const props = defineProps({ language: { type: String, default: 'lustro' } })
const period = ref('September')
const view = ref('Cash flow')
const query = ref('')
const kind = ref('All')
const selected = ref(null)
const point = ref(3)
const chartId = useId()
const amounts = { September: [4200, 1600, 4800, 1800, 3900, 1400, 5500, 2000], August: [3800, 1500, 4200, 1700, 3600, 1300, 4900, 1800] }
const labels = ['Memberships', 'Coach payroll', 'Private sessions', 'Studio rent', 'Memberships', 'Equipment', 'Workshops', 'Marketing']
const cats = ['Sales', 'People', 'Sales', 'Space', 'Sales', 'Equipment', 'Sales', 'Marketing']
const records = computed(() => amounts[period.value].map((amount, i) => ({ id: i + 1, name: labels[i], category: cats[i], amount, income: i % 2 === 0, day: [3, 5, 10, 12, 17, 19, 24, 26][i], week: Math.floor(i / 2) })))
const income = computed(() => records.value.filter(r => r.income).reduce((s, r) => s + r.amount, 0))
const expenses = computed(() => records.value.filter(r => !r.income).reduce((s, r) => s + r.amount, 0))
const net = computed(() => income.value - expenses.value)
const visible = computed(() => records.value.filter(r => (kind.value === 'All' || (kind.value === 'Income') === r.income) && `${r.name} ${r.category}`.toLowerCase().includes(query.value.toLowerCase())))
const weeks = computed(() => [0, 1, 2, 3].map(w => ({ label: `Week ${w + 1}`, revenue: records.value[w * 2].amount, expense: records.value[w * 2 + 1].amount })))
const money = n => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(n)
const y = value => 200 - value / 6000 * 160
const x = i => 64 + i * 145
const line = field => weeks.value.map((w, i) => `${x(i)},${y(w[field])}`).join(' ')
const current = computed(() => weeks.value[point.value])
const budgets = { People: 2000, Space: 2200, Equipment: 1800, Marketing: 1800 }
function resetDetail() { selected.value = null }
</script>

<template>
<div class="fin" :class="`fin-${props.language}`">
  <aside class="fin-side" aria-label="Illustrative workspace context">
    <div class="fin-brand"><span>◎</span> Northstar</div>
    <small>STUDIO FINANCE</small>
    <div class="fin-nav active">◫ &nbsp; Overview</div><div class="fin-nav">↗ &nbsp; Income</div><div class="fin-nav">↙ &nbsp; Expenses</div><div class="fin-nav">▤ &nbsp; Reports</div>
    <div class="fin-side-note">A clearer view<br>of your money.<hr>Demo workspace<br>USD · No bank connected</div>
  </aside>
  <main class="fin-main">
    <header class="fin-header"><div><span class="fin-eyebrow">WORKSPACE / FINANCE</span><h3>Money, in perspective.</h3><p>Northstar Studio · Monthly overview</p></div><label>Period<select v-model="period" @change="resetDetail"><option>September</option><option>August</option></select><small>2026 · USD</small></label></header>
    <div class="fin-banner"><span class="fin-banner-icon">↗</span><div><strong>Your month at a glance</strong><p>Income {{ money(income) }} minus expenses {{ money(expenses) }} leaves {{ money(net) }} in net cash flow.</p></div><span class="fin-chip">Fictitious data</span></div>
    <div class="fin-kpis" aria-live="polite">
      <section><span class="fin-kpi-label">● Total income</span><strong>{{ money(income) }}</strong><small>{{ period === 'September' ? '+12.7% vs August' : 'August baseline' }}</small></section>
      <section><span class="fin-kpi-label">● Total expenses</span><strong>{{ money(expenses) }}</strong><small>{{ period === 'September' ? '+7.9% vs August' : 'August baseline' }}</small></section>
      <section><span class="fin-kpi-label">● Net cash flow</span><strong>{{ money(net) }}</strong><small>Income minus expenses</small></section>
      <section><span class="fin-kpi-label">● Cash retained</span><strong>{{ (net / income * 100).toFixed(1) }}%</strong><small>Net cash flow / income</small></section>
    </div>
    <div class="fin-chart-grid">
      <section class="fin-panel fin-trend"><div class="fin-panel-head"><div><h4>Revenue performance</h4><p>Weekly totals, not a cumulative balance</p></div><div class="fin-segment" aria-label="Chart view"><button v-for="v in ['Cash flow', 'Revenue']" :key="v" :aria-pressed="view === v" @click="view = v">{{ v }}</button></div></div>
        <div class="fin-readout" aria-live="polite"><strong>{{ money(current.revenue) }}</strong><span>{{ current.label }} income<span v-if="view === 'Cash flow'"> · Expenses {{ money(current.expense) }}</span></span></div>
        <svg viewBox="0 0 540 245" role="img" aria-label="Weekly income and expense chart. Focus any income point to inspect its value.">
          <defs><linearGradient :id="chartId" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--fin-accent)" stop-opacity=".22"/><stop offset="100%" stop-color="var(--fin-accent)" stop-opacity="0"/></linearGradient></defs>
          <g v-for="v in [0, 2000, 4000, 6000]" :key="v"><line x1="64" x2="515" :y1="y(v)" :y2="y(v)" class="fin-grid-line"/><text x="8" :y="y(v) + 4">{{ v === 0 ? '$0' : `$${v / 1000}k` }}</text></g>
          <polygon :points="`64,200 ${line('revenue')} 499,200`" :fill="`url(#${chartId})`"/>
          <polyline :points="line('revenue')" fill="none" stroke="var(--fin-accent)" stroke-width="3"/>
          <polyline v-if="view === 'Cash flow'" :points="line('expense')" fill="none" stroke="var(--fin-second)" stroke-width="2" stroke-dasharray="5 5"/>
          <g v-for="(w, i) in weeks" :key="i"><text :x="x(i)" y="230" text-anchor="middle">{{ w.label }}</text><circle :cx="x(i)" :cy="y(w.revenue)" r="9" class="fin-point" tabindex="0" :aria-label="`${w.label}: income ${money(w.revenue)}, expenses ${money(w.expense)}`" @mouseenter="point = i" @focus="point = i"><title>{{ w.label }}: income {{ money(w.revenue) }}, expenses {{ money(w.expense) }}</title></circle><circle :cx="x(i)" :cy="y(w.revenue)" :r="point === i ? 5 : 3" fill="var(--fin-accent)" pointer-events="none"/></g>
        </svg>
        <div class="fin-legend"><span><i></i>Income</span><span v-if="view === 'Cash flow'"><i class="second"></i>Expenses (dashed)</span><small>Hover or focus a point</small></div>
      </section>
      <section class="fin-panel fin-budget"><div class="fin-panel-head"><div><h4>Spending plan</h4><p>Actual / monthly budget</p></div></div><div v-for="r in records.filter(r => !r.income)" :key="r.id" class="fin-budget-row"><div><strong>{{ r.category }}</strong><span>{{ money(r.amount) }} / {{ money(budgets[r.category]) }}</span></div><progress :value="r.amount" :max="budgets[r.category]" :aria-label="`${r.category} budget usage`"></progress><small>{{ Math.round(r.amount / budgets[r.category] * 100) }}% used <b v-if="r.amount > budgets[r.category]"> · Over budget</b></small></div><div class="fin-budget-note">{{ period === 'September' ? 'Marketing is $200 over plan. Review campaign costs before next month.' : 'Every category is within its monthly budget.' }}</div></section>
    </div>
    <section class="fin-panel fin-ledger"><div class="fin-panel-head"><div><h4>Transactions</h4><p>8 entries · Settled cash movements</p></div><div class="fin-filters"><label class="fin-sr" :for="`${chartId}-search`">Search transactions</label><input :id="`${chartId}-search`" v-model="query" placeholder="Search transactions"><label class="fin-sr" :for="`${chartId}-type`">Transaction type</label><select :id="`${chartId}-type`" v-model="kind"><option>All</option><option>Income</option><option>Expense</option></select></div></div><div class="fin-table-scroll"><table><thead><tr><th>Description</th><th>Date</th><th>Category</th><th class="fin-amount">Amount (USD)</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td><button class="fin-transaction" @click="selected = r"><span class="fin-arrow">{{ r.income ? '↗' : '↙' }}</span>{{ r.name }}<small>{{ r.income ? 'Income' : 'Expense' }} · Settled</small></button></td><td>{{ period.slice(0, 3) }} {{ r.day }}</td><td><span class="fin-chip">{{ r.category }}</span></td><td class="fin-amount" :class="{ 'fin-positive': r.income }">{{ r.income ? '+' : '-' }}{{ money(r.amount) }}</td></tr><tr v-if="!visible.length"><td colspan="4">No matching transactions. Clear search or choose All.</td></tr></tbody></table></div><div class="fin-ledger-foot">{{ visible.length }} of 8 entries shown · Overview totals always include the full month.</div>
      <div v-if="selected" class="fin-detail" aria-live="polite"><div><strong>{{ selected.name }}</strong><p>{{ period }} {{ selected.day }}, 2026 · {{ selected.category }} · {{ selected.income ? 'Income' : 'Expense' }} · {{ money(selected.amount) }} USD</p><small>Settled demo transaction #NS-{{ selected.id }}. No account numbers or payment actions.</small></div><button @click="selected = null" aria-label="Close transaction details">×</button></div>
    </section>
    <footer class="fin-footer">Local demonstration only. No real accounts, payments, investment advice or persistence.</footer>
  </main>
</div>
</template>

<style>
