.fin-pulsefit{--fin-bg:#f5f5f5;--fin-panel:#fff;--fin-side:#212529;--fin-line:#dedede;--fin-text:#212121;--fin-muted:#5f666d;--fin-accent:#7a5a1f;--fin-second:#5f666d;--fin-soft:#f5e6d3;--fin-positive:#11643b;font-family:'Rubik',sans-serif;border-radius:16px}
